import {SHOP,AUDIENCES,PLACEMENTS,CREATIVES,OFFERS,DEFAULT_CONFIG,validateConfig,simulate,assumptions,makeVariant,explainChange} from './engine.mjs';
const $=s=>document.querySelector(s);
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(n);
const num=n=>new Intl.NumberFormat('en-US').format(n);
const pct=n=>(n*100).toFixed(2)+'%';
const STEPS=['Your business','Build a campaign','Review & run','Read the results','Try an improvement'];
const catalogs={audience:AUDIENCES,placement:PLACEMENTS,creative:CREATIVES,offer:OFFERS};
const titles={budget:'Total budget',audience:'Audience',placement:'Placement',creative:'Ad message',offer:'Offer'};
let state=fresh();
function fresh(){return {step:0,maxStep:0,draft:{...DEFAULT_CONFIG},baseline:null,variant:null,experimentKey:'creative',experimentValue:'benefits',hypothesis:'',reviewed:false};}
function go(step){state.step=step;state.maxStep=Math.max(state.maxStep,step);render();$('#main').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
function header(k,title,desc){return `<div class="kicker"><span>0${state.step+1} / 05</span> ${k}</div><h1>${title}</h1><p class="intro">${desc}</p>`;}
function actions(back,next,label){return `<div class="actions">${back!==null?`<button class="secondary" data-go="${back}">← Back</button>`:'<span class="subtle">A guided exercise · No ad account needed</span>'}${next!==null?`<button class="primary" data-go="${next}">${label} →</button>`:''}</div>`;}
function preview(c){const offer=OFFERS[c.offer];return `<div class="preview ${c.placement!=='feed'?'vertical':''}"><div class="preview-header"><span class="avatar">E&E</span><div><strong>emberandearth</strong><small>Sponsored · Practice preview</small></div></div><img src="candle.png" alt="Ember & Earth amber candle with dried orange and linen" width="1024" height="1024"><div class="preview-cta">Shop now <span aria-hidden="true">↗</span></div><div class="preview-copy"><strong>emberandearth</strong> ${esc(CREATIVES[c.creative].caption)} ${offer.discount?'Save 15% this week.':''}</div></div><p class="subtle">${c.placement==='reels'?'Reels storyboard frame; this exercise does not create a video.':'Simplified '+PLACEMENTS[c.placement].label+' preview.'} Product image is AI-generated for this fictional shop.</p>`;}
function options(key,value,opts=catalogs[key]){return Object.entries(opts).map(([v,o])=>`<label class="choice"><input type="radio" name="${key}" value="${v}" ${v===value?'checked':''}><span><strong>${esc(o.label)}</strong><small>${esc(o.description)}</small></span></label>`).join('');}
const placementLessons={feed:'A product image sits in the feed. In this scenario, it costs more per impression but earns a higher click probability.',stories:'A full-screen vertical concept. In this scenario, impression cost and click probability both sit between Feed and Reels.',reels:'A short-video setting. Our prepared concept gets cheaper impressions but a lower click probability. A stronger video could behave differently in reality.'};
function placementGuide(c,selected=c.placement){
 const safe={...c,name:c.name.trim()||'Practice campaign'};
 const rows=Object.keys(PLACEMENTS).map(k=>simulate({...safe,placement:k}));
 return `<div class="placement-guide"><h3>What does placement change?</h3><p class="subtle">${placementLessons[selected]}</p><div class="table-scroll"><table><caption class="subtle">Same ${money(c.budget)} budget, audience, message, and offer</caption><thead><tr><th>Placement</th><th>Cost / 1,000 views</th><th>Click chance</th><th>Expected orders</th></tr></thead><tbody>${rows.map(r=>`<tr class="${r.config.placement===selected?'selected-placement':''}"><th>${PLACEMENTS[r.config.placement].label.replace('Instagram ','')}${r.config.placement===selected?' · selected':''}</th><td>${money(r.model.baseCpm)}</td><td>${pct(r.model.clickProbability)}</td><td>${r.expectedPurchases.toFixed(1)}</td></tr>`).join('')}</tbody></table></div><p class="subtle">Expected orders are a mathematical average, not guaranteed sales. Individual runs produce whole-number orders. These are fictional assumptions for this exercise, not platform benchmarks or a universal placement ranking.</p></div>`;
}
function refreshComparisonNotice(){const el=$('#comparison-pending');if(!el||!state.variant)return;el.hidden=state.variant.changeKey===state.experimentKey&&state.variant.config[state.experimentKey]===state.experimentValue&&state.variant.hypothesis===state.hypothesis.trim();}
function business(){return header('MEET YOUR BUSINESS','Small shop. Big first step.','Understand how to run effective Instagram ad campaigns—by practicing before you spend.')+`<div class="grid"><section class="panel business-panel"><img class="product-photo" src="candle.png" alt="Ember & Earth candle on a warm tabletop" width="1024" height="1024"><div class="business-info"><p class="eyebrow">YOUR PRACTICE BUSINESS</p><h2>Ember & Earth</h2><p class="muted">Small-batch candles for everyday rituals. Help a new online shop turn Instagram attention into purchases.</p><div class="facts"><div class="fact"><strong>$32</strong><span>Price per candle</span></div><div class="fact"><strong>$12</strong><span>Cost per order</span></div><div class="fact"><strong>$20</strong><span>Margin before ads</span></div></div></div></section><section class="panel brief"><p class="eyebrow">THE CHALLENGE</p><div class="budget-number">$300<small>in practice money</small></div><p>Run a 7-day campaign. Then change one decision and see whether your results improve.</p></section><section class="panel"><h2>What you’ll learn</h2><ol class="lesson-list"><li>Connect an audience, an ad, and an offer.</li><li>Understand where your budget goes.</li><li>Use results to make your next decision.</li></ol></section></div>`+actions(null,1,'Build my campaign');}
function builder(){const c=state.draft;return header('MAKE YOUR DECISIONS','Build your first campaign.','Start with the suggested settings or make your own choices. Each explanation tells you what the decision means.')+`<form id="campaign-form"><div class="form-grid"><div><section class="panel"><div class="section-title"><span>CAMPAIGN</span><h2>What are you trying to achieve?</h2></div><div class="field"><label for="campaign-name">Campaign name</label><input id="campaign-name" type="text" name="name" maxlength="70" required value="${esc(c.name)}"></div><div class="readout"><strong>Objective: Sales</strong><br>We’re practicing purchases on a website. Clicks help people get there; purchases are the outcome we care about.</div></section><section class="panel" style="margin-top:20px"><div class="section-title"><span>AD SET</span><h2>Who, where, and how much?</h2></div><div class="field"><div class="amount-row"><label for="budget">Total budget for 7 days</label><output id="budget-value">${money(c.budget)}</output></div><input id="budget" name="budget" type="range" min="50" max="300" step="10" value="${c.budget}"><p class="subtle">$50–$300 total · about <span id="daily-budget">${money(c.budget/7)}</span> per day. In this exercise, your budget is spent evenly.</p></div><fieldset><legend>Audience</legend>${options('audience',c.audience)}</fieldset><fieldset><legend>Instagram placement</legend>${options('placement',c.placement)}</fieldset><div id="placement-guide">${placementGuide(c)}</div><div class="note">An ad set groups the audience, placement, and spending decisions. This exercise uses one ad set and one ad to keep the learning clear.</div></section><section class="panel" style="margin-top:20px"><div class="section-title"><span>AD</span><h2>What will people see?</h2></div><fieldset><legend>Choose your message</legend>${options('creative',c.creative)}</fieldset><fieldset><legend>Choose your offer</legend>${options('offer',c.offer)}</fieldset><div class="readout"><strong>Call to action:</strong> Shop now<br><strong>Destination:</strong> Ember & Earth’s fictional product page</div><p class="subtle">Use the prepared ad concepts for this first lesson. Free-text creative editing and real website connections aren’t part of this exercise.</p></section></div><aside class="panel sticky"><p class="eyebrow">YOUR AD PREVIEW</p><div id="ad-preview">${preview(c)}</div><div class="learning"><strong>Think before you spend</strong><p>Who is this for? What makes the candle worth buying? Does your message answer both?</p></div></aside></div><p id="form-error" class="error" role="alert"></p><div class="actions"><button type="button" class="secondary" data-go="0">← Your business</button><button type="submit" class="primary">Review my campaign →</button></div></form>`;}
function summary(c){return [['Objective','Website sales'],['Audience',AUDIENCES[c.audience].label],['Placement',PLACEMENTS[c.placement].label],['Message',CREATIVES[c.creative].label],['Offer',OFFERS[c.offer].label],['Schedule','7 simulated days'],['Total budget',money(c.budget)]].map(([l,v])=>`<div class="summary-row"><span>${l}</span><strong>${esc(v)}</strong></div>`).join('');}
function review(){const c=state.draft,m=assumptions(c);return header('CHECK YOUR PLAN','Ready for a practice run?','Review your choices, then fast-forward through one fictional week. You can come back and change your setup.')+`<div class="form-grid"><section class="panel"><h2>${esc(c.name)}</h2>${summary(c)}<div class="note"><strong>The business math</strong><br>Each order brings in ${money(m.orderPrice)} and costs ${money(SHOP.unitCost)} to fulfill. You need at least <strong>${Math.ceil(c.budget/(m.orderPrice-SHOP.unitCost))} orders</strong> to cover this ad budget and those order costs.</div><label class="review-check"><input id="acknowledge" type="checkbox" ${state.reviewed?'checked':''}><span>I understand these are fictional teaching assumptions, not forecasts or Meta performance benchmarks.</span></label><p class="subtle">Campaigns stay in this browser tab for this visit. Reloading starts a new exercise.</p><p id="run-error" class="error" role="alert"></p></section><section class="panel"><p class="eyebrow">${PLACEMENTS[c.placement].label.toUpperCase()}</p>${preview(c)}</section></div><div class="actions"><button class="secondary" data-go="1">← Edit campaign</button><button id="run" class="primary" ${state.reviewed?'':'disabled'}>Simulate 7 days →</button></div>`;}
function metric(label,value,detail,cls=''){return `<div class="metric"><span>${label}</span><strong class="${cls}">${value}</strong><small>${detail}</small></div>`;}
function observations(r){let out=[];out.push(`<div class="learning"><strong>${r.purchases} purchases from ${num(r.clicks)} clicks</strong><p>${pct(r.cvr)} of visitors purchased. Clicks and purchases measure different parts of the journey; a cheaper click isn’t automatically a better customer.</p></div>`);out.push(`<div class="learning"><strong>${r.contribution>=0?'This run covered its modeled costs.':'Revenue is not profit.'}</strong><p>${money(r.revenue)} revenue − ${money(r.productCost)} order costs − ${money(r.spend)} ads = ${money(r.contribution)} contribution after ads. Rent, salaries, taxes, returns, and repeat purchases are outside this model.</p></div>`);out.push(`<div class="learning"><strong>Choose one question to investigate</strong><p>${r.config.offer==='save15'?'The discount helps conversion in our model but reduces each order’s margin. Would full price leave more after costs?':r.config.creative==='mood'?'Would explaining the scent, burn time, and price make more visitors confident enough to buy?':'Would a different audience, placement, or offer improve contribution after ads?'}</p></div>`);return out.join('');}
function results(){const r=state.baseline;if(!r)return business();return header('FOLLOW THE CUSTOMER JOURNEY','Your first results are in.','These are simulated outcomes from your choices. Read the whole journey before deciding what to change.')+`<span class="pill">Original campaign · 7 days · ${esc(r.config.name)}</span><div class="metrics">${metric('Ad spend',money(r.spend),'Total practice budget used')}${metric('Purchases',num(r.purchases),'One candle per order')}${metric('Revenue',money(r.revenue),r.roas.toFixed(2)+'× return on ad spend')}${metric('After order costs & ads',money(r.contribution),'Contribution, not net profit',r.contribution<0?'negative':'positive')}</div><div class="grid"><section class="panel"><h2>From attention to action</h2><div class="funnel">${[['Impressions',r.impressions,100,'Times the ad was shown'],['Website clicks',r.clicks,Math.max(5,r.ctr*100),'Click-through rate: '+pct(r.ctr)],['Purchases',r.purchases,Math.max(2,r.purchases/r.impressions*100),'Purchase conversion: '+pct(r.cvr)]].map(([l,v,w,h])=>`<div><div class="funnel-label"><span>${l}</span><strong>${num(v)}</strong></div><div class="track"><i style="width:${w}%"></i></div><p class="subtle" style="margin:5px 0 0">${h}</p></div>`).join('')}</div><p class="subtle">Bars have a minimum visible width; use the counts for exact proportions.</p><div class="summary-row"><span>Cost per click</span><strong>${r.cpc===null?'No clicks':money(r.cpc)}</strong></div><div class="summary-row"><span>Cost per purchase</span><strong>${r.cpa===null?'No purchases':money(r.cpa)}</strong></div><div class="summary-row"><span>Break-even purchase cost</span><strong>${money(r.model.orderPrice-SHOP.unitCost)}</strong></div></section><section class="panel"><h2>What should you notice?</h2>${observations(r)}</section><section class="panel wide"><h2>One week, day by day</h2><p class="subtle">Purchases fluctuate. One day alone doesn’t tell the whole story.</p><div class="chart" role="img" aria-label="Purchases per day: ${r.daily.map(d=>'day '+d.day+': '+d.purchases).join(', ')}">${r.daily.map(d=>`<div class="bar-group"><span>${d.purchases}</span><i style="height:${d.purchases/Math.max(1,...r.daily.map(x=>x.purchases))*95}px"></i><small>Day ${d.day}</small></div>`).join('')}</div><details><summary>View daily numbers</summary><div class="table-scroll"><table><caption class="subtle">Original campaign · simulated daily results</caption><thead><tr><th>Day</th><th>Spend</th><th>Impressions</th><th>Clicks</th><th>Purchases</th></tr></thead><tbody>${r.daily.map(d=>`<tr><td>${d.day}</td><td>${money(d.spend)}</td><td>${num(d.impressions)}</td><td>${d.clicks}</td><td>${d.purchases}</td></tr>`).join('')}</tbody></table></div></details></section></div>`+actions(2,4,'Try an improvement');}
function valueLabel(key,value){return key==='budget'?money(value):catalogs[key][value].label;}
function experimentOptions(){const k=state.experimentKey;if(k==='budget')return `<label for="experiment-value">New total budget</label><input type="number" id="experiment-value" min="50" max="300" step="1" required value="${esc(state.experimentValue)}">`;return `<label for="experiment-value">New ${titles[k].toLowerCase()}</label><select id="experiment-value">${Object.entries(catalogs[k]).filter(([v])=>v!==state.baseline.config[k]).map(([v,o])=>`<option value="${v}" ${v===state.experimentValue?'selected':''}>${esc(o.label)}</option>`).join('')}</select>`;}
function causalExplanation(a,b){
 const x=explainChange(a,b,b.changeKey);const signed=n=>(n>0?'+':'')+money(n);
 return `<section class="causal-panel"><p class="eyebrow">WHY DID THIS HAPPEN?</p><h3>${esc(x.title)}</h3><p>${esc(x.reason)}</p><ol class="cause-chain">${x.steps.map((s,i)=>`<li><span class="cause-number">${i+1}</span><div><strong>${esc(s.label)}</strong><div class="cause-values">${esc(s.before)} <span aria-hidden="true">→</span> ${esc(s.after)}</div><p>${esc(s.detail)}</p></div></li>`).join('')}</ol><div class="readout"><strong>Why the actual result can differ from the average</strong><p>${esc(x.realized)}</p></div><h3 style="margin-top:22px">Where the money difference came from</h3><div class="summary-row"><span>More / fewer orders, at the original margin</span><strong>${signed(x.contribution.volume)}</strong></div><div class="summary-row"><span>Change in price on experiment orders</span><strong>${signed(x.contribution.price)}</strong></div><div class="summary-row"><span>Lower / higher ad spending</span><strong>${signed(x.contribution.spend)}</strong></div><div class="summary-row"><span>Total contribution change</span><strong>${signed(x.contribution.total)}</strong></div><div class="learning"><strong>What to take into a real campaign</strong><p>${esc(x.takeaway)}</p></div></section>`;
}
function comparison(){const a=state.baseline,b=state.variant;if(!b)return `<section class="panel comparison"><span class="pill">YOUR NEXT EXPERIMENT</span><h2>One change.<br>A clearer lesson.</h2><p>Keep the original as your baseline. Change one decision so you can trace the difference in results.</p><div class="budget-number">${money(a.contribution)}</div><span class="next-label">ORIGINAL CONTRIBUTION AFTER ADS</span><p>Both runs use the same fictional market conditions. Repeating identical settings produces identical results.</p></section>`;const diff=Math.round((b.contribution-a.contribution)*100)/100;return `<section class="panel"><span class="pill">LAST COMPLETED EXPERIMENT</span><p id="comparison-pending" class="note" role="status" hidden>New choices are pending. Run your experiment to update this comparison.</p><h2 style="margin-top:16px">${diff>0?'More left after costs.':diff<0?'This change cost you margin.':a.purchases===b.purchases?'Same sales. Different journey.':'Different trade-offs. Same contribution.'}</h2><p class="subtle">${esc(titles[b.changeKey])}: ${esc(valueLabel(b.changeKey,a.config[b.changeKey]))} → ${esc(valueLabel(b.changeKey,b.config[b.changeKey]))}</p><div class="table-scroll"><table><caption class="subtle">Original versus your latest experiment</caption><thead><tr><th>Measure</th><th>Original</th><th>Experiment</th></tr></thead><tbody>${[['Ad spend',money(a.spend),money(b.spend)],['Impressions',num(a.impressions),num(b.impressions)],['Click-through rate',pct(a.ctr),pct(b.ctr)],['Cost per click',a.cpc===null?'—':money(a.cpc),b.cpc===null?'—':money(b.cpc)],['Expected orders (model average)',a.expectedPurchases.toFixed(1),b.expectedPurchases.toFixed(1)],['Clicks',num(a.clicks),num(b.clicks)],['Purchases',num(a.purchases),num(b.purchases)],['Revenue',money(a.revenue),money(b.revenue)],['Order costs',money(a.productCost),money(b.productCost)],['After costs & ads',money(a.contribution),money(b.contribution)]].map(row=>`<tr>${row.map((v,i)=>`<${i?'td':'th'}>${v}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</tbody></table></div><div class="note"><strong>${diff>=0?'+':''}${money(diff)} contribution change</strong><br>${b.changeKey==='placement'?`Placement changes impression cost and click probability in this scenario. Expected orders shift from ${a.expectedPurchases.toFixed(1)} to ${b.expectedPurchases.toFixed(1)}. ${a.purchases===b.purchases?`Both runs happened to produce ${a.purchases} purchases, so revenue and contribution are tied even though traffic changed.`:'The resulting purchase totals reflect those assumptions plus the fixed random scenario.'}`:b.changeKey==='offer'?'A discount changes both the number of orders and the margin on each order. Judge both together.':b.changeKey==='budget'?'Compare total contribution and cost per purchase. Lower spend can reduce losses without finding a more effective ad.':'In this teaching model, your choice changes cost, click probability, or purchase probability. The assumptions are visible below.'}</div>${causalExplanation(a,b)}<p class="subtle"><strong>Your prediction:</strong> ${esc(b.hypothesis)}</p><p class="subtle">This comparison illustrates the model, not a statistically proven real-world result. Real campaigns need enough data and a controlled test.</p><button id="download" class="secondary">Download my learning summary ↓</button></section>`;}
function experiment(){return header('MAKE ONE CHANGE','What would you try next?','Good experiments start with a question. Predict what will happen, change one decision, and compare with your original.')+`<div class="grid" style="align-items:start"><form id="experiment-form" class="panel"><h2>Your experiment</h2><div class="field"><label for="experiment-key">Which decision will you change?</label><select id="experiment-key">${Object.entries(titles).map(([k,t])=>`<option value="${k}" ${state.experimentKey===k?'selected':''}>${t}</option>`).join('')}</select><p class="subtle">Original: ${esc(valueLabel(state.experimentKey,state.baseline.config[state.experimentKey]))}</p></div><div class="field">${experimentOptions()}</div>${state.experimentKey==='placement'?`<div id="experiment-placement-guide">${placementGuide(state.baseline.config,state.experimentValue)}</div>`:''}<div class="field"><label for="hypothesis">What do you expect, and why?</label><textarea id="hypothesis" minlength="8" maxlength="500" required placeholder="I think a clearer product message will help more visitors decide to buy.">${esc(state.hypothesis)}</textarea><p class="subtle">Your prediction is saved with the comparison. It does not change the calculation.</p></div><p class="note">Your original campaign stays unchanged. We reuse the same 7-day market scenario for a fairer practice comparison.</p><p class="error" id="experiment-error" role="alert"></p><button type="submit" class="primary" style="width:100%">Run my experiment →</button></form><div id="comparison">${comparison()}</div></div><div class="actions"><button class="secondary" data-go="3">← Original results</button><button class="text-button" data-model>Understand the assumptions</button></div>`;}
function render(){
 $('#steps').innerHTML=STEPS.map((s,i)=>`<button class="step ${i===state.step?'active':i<state.step?'done':''}" aria-label="Step ${i+1}: ${s}" data-go="${i}" ${i>state.maxStep?'disabled':''} ${i===state.step?'aria-current="step"':''}><b>${i<state.step?'✓':i+1}</b><span class="step-label">${s}</span></button>`).join('');
 $('#main').innerHTML=`<div class="screen-enter">${[business,builder,review,results,experiment][state.step]()}</div>`;
 bind();refreshComparisonNotice();
}
function readDraft(){const f=$('#campaign-form');if(!f)return;const data=new FormData(f);state.draft={name:String(data.get('name')),budget:Number(data.get('budget')),audience:data.get('audience'),placement:data.get('placement'),creative:data.get('creative'),offer:data.get('offer')};}
function clearResults(){state.baseline=null;state.variant=null;state.reviewed=false;state.maxStep=1;}
function setExperimentKey(k){state.experimentKey=k;state.experimentValue=k==='budget'?(state.baseline.config.budget===150?200:150):Object.keys(catalogs[k]).find(v=>v!==state.baseline.config[k]);}
function runBaseline(){if(!state.reviewed)throw new Error('Please acknowledge the simulation assumptions first.');state.baseline=simulate(state.draft);state.variant=null;state.hypothesis='';setExperimentKey('creative');go(3);return state.baseline;}
function runExperiment(){if(state.hypothesis.trim().length<8||state.hypothesis.length>500)throw new Error('Write a short prediction (8–500 characters) before running.');const config=makeVariant(state.baseline.config,state.experimentKey,state.experimentValue);const result=simulate(config);state.variant={...result,changeKey:state.experimentKey,hypothesis:state.hypothesis.trim()};render();$('#comparison').setAttribute('tabindex','-1');$('#comparison').focus({preventScroll:true});return state.variant;}
function bind(){
 document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{if(state.step===1)readDraft();go(Number(b.dataset.go));});
 document.querySelectorAll('[data-model]').forEach(b=>b.onclick=showModel);
 const f=$('#campaign-form');if(f){f.addEventListener('input',()=>{readDraft();clearResults();$('#budget-value').textContent=money(state.draft.budget);$('#daily-budget').textContent=money(state.draft.budget/7);$('#ad-preview').innerHTML=preview(state.draft);$('#placement-guide').innerHTML=placementGuide(state.draft);$('#steps').querySelectorAll('[data-go]').forEach(b=>{if(Number(b.dataset.go)>1)b.disabled=true;});});f.onsubmit=e=>{e.preventDefault();try{readDraft();state.draft=validateConfig(state.draft);go(2);}catch(err){$('#form-error').textContent=err.message;}};}
 if($('#acknowledge'))$('#acknowledge').onchange=e=>{state.reviewed=e.target.checked;$('#run').disabled=!state.reviewed;};
 if($('#run'))$('#run').onclick=()=>{try{runBaseline();}catch(err){$('#run-error').textContent=err.message;}};
 if($('#experiment-form')){
  $('#experiment-key').onchange=e=>{state.hypothesis=$('#hypothesis').value;setExperimentKey(e.target.value);render();};
  $('#experiment-value').oninput=e=>{state.experimentValue=state.experimentKey==='budget'?Number(e.target.value):e.target.value;refreshComparisonNotice();if(state.experimentKey==='placement')$('#experiment-placement-guide').innerHTML=placementGuide(state.baseline.config,state.experimentValue);};
  $('#hypothesis').oninput=e=>{state.hypothesis=e.target.value;refreshComparisonNotice();};
  $('#experiment-form').onsubmit=e=>{e.preventDefault();try{runExperiment();}catch(err){$('#experiment-error').textContent=err.message;}};
 }
 if($('#download'))$('#download').onclick=download;
}
function showModel(){const c=state.baseline?.config??state.draft;let m;try{m=assumptions(c);}catch{m=assumptions(DEFAULT_CONFIG);}
 $('#model-content').innerHTML=`<p>This is a deliberately small, fictional model for learning. None of these numbers are Meta benchmarks, real audience estimates, or forecasts.</p><h3>The journey</h3><p>Budget buys impressions. Some impressions lead to clicks. Some clicks lead to purchases. Each purchase adds revenue and fulfillment cost.</p><div class="readout">Impressions ≈ spend ÷ cost per 1,000 impressions × 1,000<br>Revenue = purchases × order price<br>Contribution = revenue − order costs − ad spend</div><h3 style="margin-top:24px">The original campaign’s assumptions</h3><ul class="lesson-list"><li>Base cost per 1,000 impressions: ${money(m.baseCpm)}.</li><li>Click probability per impression: ${pct(m.clickProbability)}.</li><li>Purchase probability per click: ${pct(m.purchaseProbability)}.</li><li>Order price: ${money(m.orderPrice)}; fulfillment cost: $12.</li></ul><h3 style="margin-top:24px">What each control changes</h3><p class="subtle">Feed starts at $12 per 1,000 impressions and 1.2% click probability; Stories at $10.50 and 0.9%; Reels at $9 and 0.78%. These choices describe this shop’s fictional prepared creative, not which placement performs best in reality.</p><p class="subtle">Home & interiors increases cost per 1,000 impressions by 18%, click probability by 25%, and purchase probability by 20%. Product-focused copy increases click probability by 22% and purchase probability by 14%. The 15% discount raises purchase probability by 28% while reducing price. The starting purchase probability is 4%.</p><p class="subtle">Spending above $150 adds up to 12% to impression cost at $300. Each day’s cost varies within ±12%. Purchases use seeded random draws; each rerun uses the same scenario. The full budget is spent evenly across 7 days.</p><h3>What we leave out</h3><p class="subtle">Real auctions, repeat views, attribution windows, tracking gaps, learning phases, stock limits, organic sales, returns, taxes, overhead, and repeat customers. We don’t analyze your written prediction with AI. No real ads are sent to Instagram.</p>`;
 $('#model-dialog').showModal();}
function download(){const a=state.baseline,b=state.variant;const explanation=explainChange(a,b,b.changeKey);const lines=['CAMPAIGN LAB — MY LEARNING SUMMARY','Instagram practice · Fictional Ember & Earth shop','',`Campaign: ${a.config.name}`,`Question: ${b.hypothesis}`,`Change: ${titles[b.changeKey]} — ${valueLabel(b.changeKey,a.config[b.changeKey])} -> ${valueLabel(b.changeKey,b.config[b.changeKey])}`,'','Measure | Original | Experiment',...['spend','clicks','purchases','revenue','productCost','contribution'].map(k=>`${k}: ${a[k]} | ${b[k]}`),'','WHY THIS HAPPENED',explanation.reason,...explanation.steps.map(s=>s.label+': '+s.before+' -> '+s.after+'. '+s.detail),explanation.realized,explanation.takeaway,'','Contribution = revenue - fulfillment costs - advertising. It is not net profit.','All outcomes are simulated using fictional teaching assumptions. They are not performance forecasts.','The same seeded market conditions are used for both runs.'];const url=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'}));const aLink=document.createElement('a');aLink.href=url;aLink.download='campaign-lab-learning-summary.txt';document.body.append(aLink);aLink.click();aLink.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#restart').onclick=()=>$('#reset-dialog').showModal();
$('#cancel-reset').onclick=()=>$('#reset-dialog').close();
$('#confirm-reset').onclick=()=>{$('#reset-dialog').close();state=fresh();render();$('#main').focus();};
$('#assumptions').onclick=showModel;$('#close-model').onclick=()=>$('#model-dialog').close();
render();
// Optional browser-native agent interface. Uses the same state and actions as the UI.
if(document.modelContext?.registerTool){
 const lifetime=new AbortController();window.addEventListener('pagehide',()=>lifetime.abort(),{once:true});
 const tools=[{name:'read_campaign_exercise',description:'Read the current campaign choices and simulated results for this visit.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({step:state.step+1,draft:{...state.draft},original:state.baseline,experiment:state.variant})},{name:'configure_practice_campaign',description:'Stage a complete fictional campaign and open review. Does not run it or publish any real ads.',inputSchema:{type:'object',properties:{name:{type:'string',minLength:1,maxLength:70},budget:{type:'integer',minimum:50,maximum:300},audience:{enum:['broad','decor']},placement:{enum:['feed','stories','reels']},creative:{enum:['mood','benefits']},offer:{enum:['none','save15']}},required:['name','budget','audience','placement','creative','offer'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{const valid=validateConfig(input);state.draft=valid;clearResults();go(2);return {status:'staged',campaign:valid};}},{name:'run_practice_campaign',description:'Run the staged fictional campaign after acknowledging simulated assumptions. No real ads or money.',inputSchema:{type:'object',properties:{acknowledgeSimulation:{type:'boolean',const:true}},required:['acknowledgeSimulation'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(input?.acknowledgeSimulation!==true)throw new Error('Explicit acknowledgement required.');validateConfig(state.draft);state.reviewed=true;return runBaseline();}}];
 for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifetime.signal})).catch(()=>{});}catch{}}
}
